package local.mediacenter.library
import org.json.*
import org.junit.Test
import org.junit.Assert.*
class PodcastInboxPlanTest {
 private fun raw()=JSONObject("""{"id":"show","mediaType":"podcast","media":{"metadata":{"title":"Show"},"episodes":[{"id":"a","title":"Daily Interview","publishedAt":200,"audioFile":{"duration":1800}},{"id":"b","title":"Daily Trailer","publishedAt":300,"audioFile":{"duration":60}},{"id":"c","title":"Daily Interview","publishedAt":100,"audioFile":{"duration":1200}},{"id":"unavailable","title":"Future","publishedAt":400}]}}""")
 private fun rule()=PodcastInboxRule("account","show","Show",include="interview",exclude="trailer",minSeconds=600.0,maxSeconds=2000.0,limit=10)
 @Test fun titleDurationAndSeenFiltersKeepIndependentEpisodeIds(){val e=PodcastInboxPlan.episodes("account","show",raw(),JSONObject("""{"mediaProgress":[]}"""));assertEquals(listOf("a","c"),PodcastInboxPlan.select(rule(),e,emptySet()).map{it.getString("episode")});assertEquals(listOf("c"),PodcastInboxPlan.select(rule(),e,setOf("a")).map{it.getString("episode")})}
 @Test fun finishedProgressIsShowScopedAndAWholeBookCannotCompleteAnEpisode(){val user=JSONObject("""{"mediaProgress":[{"libraryItemId":"show","episodeId":"a","isFinished":true},{"libraryItemId":"other-show","episodeId":"c","isFinished":true},{"libraryItemId":"show","episodeId":null,"isFinished":true}]}""");val e=PodcastInboxPlan.episodes("account","show",raw(),user);assertEquals(listOf("c"),PodcastInboxPlan.select(rule(),e,emptySet()).map{it.getString("episode")})}
 @Test fun unknownProgressDoesNotBecomeUnplayed(){val user=JSONObject("""{"mediaProgress":[{"libraryItemId":null,"episodeId":"a","isFinished":true}]}""");val e=PodcastInboxPlan.episodes("account","show",raw(),user);assertEquals(listOf("c"),PodcastInboxPlan.select(rule(),e,emptySet()).map{it.getString("episode")})}
 @Test fun unavailableAudioIsExcludedAndNewestEligibleEpisodesRespectTheLimit(){val e=PodcastInboxPlan.episodes("account","show",raw(),JSONObject("""{"mediaProgress":[]}"""));assertEquals(3,e.size);assertEquals("a",PodcastInboxPlan.select(rule().copy(limit=1),e,emptySet()).single().getString("episode"))}
 @Test fun booksAndUnknownMediaCannotBeScannedAsShows(){for(kind in listOf("book","unknown")){try{PodcastInboxPlan.episodes("account","show",raw().put("mediaType",kind),JSONObject("""{"mediaProgress":[]}"""));fail("Accepted $kind")}catch(_:IllegalArgumentException){}}}
 @Test fun malformedRulesAndUncertainProgressFailBeforeChangingTheInbox(){for(update in listOf(JSONObject().put("limit",0),JSONObject().put("limit",1.5),JSONObject().put("enabled","true"),JSONObject().put("minSeconds",JSONObject.NULL),JSONObject().put("maxSeconds",10).put("minSeconds",20),JSONObject().put("show",""))){val value=rule().json();update.keys().forEach{value.put(it,update.get(it))};try{PodcastInboxRule.parse(value);fail("Accepted invalid rule")}catch(_:IllegalArgumentException){}};try{PodcastInboxPlan.episodes("account","show",raw(),JSONObject());fail("Accepted missing progress snapshot")}catch(_:JSONException){}}
 @Test fun onlyRequiredPodcastProgressFieldsRemainInTheScanCache(){val p=PodcastInboxPlan.progressSnapshot(JSONObject("""{"accessToken":"must-not-copy","mediaProgress":[{"libraryItemId":"book","episodeId":null,"isFinished":true},{"libraryItemId":"show","episodeId":"a","isFinished":true,"currentTime":60,"extra":"private"}]}"""));assertEquals(1,p.getJSONArray("mediaProgress").length());assertFalse(p.toString().contains("must-not-copy"));assertFalse(p.toString().contains("private"));assertEquals(listOf("c"),PodcastInboxPlan.select(rule(),PodcastInboxPlan.episodes("account","show",raw(),p),emptySet()).map{it.getString("episode")})}
 @Test fun malformedOrConflictingEpisodeProgressIsNeverAssumedUnfinished(){val user=JSONObject("""{"mediaProgress":[{"libraryItemId":"show","episodeId":"a"}]}""");assertEquals(listOf("c"),PodcastInboxPlan.select(rule(),PodcastInboxPlan.episodes("account","show",raw(),user),emptySet()).map{it.getString("episode")});user.getJSONArray("mediaProgress").put(JSONObject("""{"libraryItemId":"show","episodeId":"a","isFinished":false}"""));try{PodcastInboxPlan.episodes("account","show",raw(),user);fail("Accepted conflicting progress records")}catch(_:IllegalArgumentException){}}
}
